def listalecker(lista):
    if not lista:
        return False
    n = len(lista)
    contador = 0
    for i in range(n):
        if i == 0:
            if n == 1:
                contador += 1
            else:
                if lista[0] > lista[1]:
                    contador += 1
        elif i == n - 1:
            if lista[i] > lista[i-1]:
                contador += 1
        else:
            if lista[i] > lista[i-1] and lista[i] > lista[i+1]:
                contador += 1
    return contador == 1

def main_solution(list_a, list_b):
    result_a = listalecker(list_a)
    result_b = listalecker(list_b)
    return {"result_a": result_a, "result_b": result_b}
