def main_solution(actor_x, actor_y, collider_x, collider_y, width, height):
    class Collider:
        def __init__(self, x, y, w, h):
            self.x = x
            self.y = y
            self.width = w
            self.height = h

        def translate(self, dx, dy):
            return Collider(self.x + dx, self.y + dy, self.width, self.height)

    class Actor:
        def __init__(self, collider):
            self.x = 0
            self.y = 0
            self.collider = collider

        def globalCollider(self):
            return self.collider.translate(self.x, self.y)

    # Create actor with initial position (0,0) and given collider
    actor = Actor(Collider(collider_x, collider_y, width, height))
    # Set actor's world position
    actor.x = actor_x
    actor.y = actor_y

    # Calculate global collider
    global_collider = actor.globalCollider()

    return {
        "x": global_collider.x,
        "y": global_collider.y,
        "width": global_collider.width,
        "height": global_collider.height
    }
