class TreeNode(object):
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

class Solution:
    def sum(self, root, preSum):
        if root == None: 
            return 0
        preSum = preSum * 10 + root.val
        if root.left == None and root.right == None: 
            return preSum
        return self.sum(root.left, preSum) + self.sum(root.right, preSum)

    def sumNumbers(self, root):
        return self.sum(root, 0)

def build_tree_from_list(nodes):
    if not nodes:
        return None
    root = TreeNode(nodes[0])
    queue = [root]
    i = 1
    while queue and i < len(nodes):
        current = queue.pop(0)
        if nodes[i] is not None:
            current.left = TreeNode(nodes[i])
            queue.append(current.left)
        i += 1
        if i < len(nodes):
            if nodes[i] is not None:
                current.right = TreeNode(nodes[i])
                queue.append(current.right)
        i += 1
    return root

def main_solution(tree_nodes):
    root = build_tree_from_list(tree_nodes)
    solution = Solution()
    result = solution.sumNumbers(root)
    return result
```

