def main_solution(limit):
    if limit <= 1:
        return 1
    dict_sequenceLength = {}
    for n in range(1, limit):
        temp = n
        current = n
        sequence = [current]
        while current != 1:
            if current % 2 == 0:
                current = current // 2
            else:
                current = 3 * current + 1
            if current in dict_sequenceLength:
                length = len(sequence) + dict_sequenceLength[current]
                dict_sequenceLength[temp] = length
                break
            else:
                sequence.append(current)
        else:  # executed only if loop didn't break
            dict_sequenceLength[temp] = len(sequence)
    max_length = max(dict_sequenceLength.values())
    for key, value in dict_sequenceLength.items():
        if value == max_length:
            return key
    return 1  # fallback
```

