import itertools

def main_solution(x, n):
    # Generate Fibonacci numbers up to x with unique values
    fib = [1, 2]
    while True:
        next_fib = fib[-1] + fib[-2]
        if next_fib > x:
            break
        fib.append(next_fib)
    # Check all combinations of n distinct Fibonacci numbers
    for combo in itertools.combinations(fib, n):
        if sum(combo) == x:
            return True
    return False
