months = ['January', 'February', 'March', 'April', 'May', 'June',
          'July', 'August', 'September', 'October', 'November', 'December']
abbr_month = [m[:3].lower() for m in months]

def valid_month(month):
    """Validation of a month"""
    if month:
        if month.lower() in abbr_month or month.title() in months:
            return month.title()
    return None

def valid_day(day):
    """Validation of a day"""
    if not day.isdigit():
        return None
    d = int(day)
    if 1 <= d <= 31:
        return d
    return None

def valid_year(year):
    """Validation of a year"""
    if not year.isdigit():
        return None
    year = int(year)
    if 1900 < year < 2100:
        return year
    return None

def main_solution(month, day, year):
    """
    Validates a date input according to specified rules.
    Inputs must be JSON serializable strings.
    Returns JSON serializable dictionary with validation results.
    """
    errors = []

    # Validate month
    if not valid_month(month):
        errors.append("Month is invalid")

    # Validate day
    if not valid_day(day):
        errors.append("Day is invalid")

    # Validate year
    if not valid_year(year):
        errors.append("Year is invalid")

    return {
        "is_valid": len(errors) == 0,
        "errors": errors
    }
