class Solution:
    def __init__(self):
        self.stackIn = []
        self.stackOut = []

    def push(self, node):
        self.stackIn.append(node)

    def pop(self):
        if not self.stackOut:
            while self.stackIn:
                self.stackOut.append(self.stackIn.pop())
            return self.stackOut.pop()
        else:
            return self.stackOut.pop()

def main_solution(operations):
    solution = Solution()
    results = []
    for op in operations:
        if op[0] == "push":
            solution.push(op[1])
        elif op[0] == "pop":
            results.append(solution.pop())
    return results
