class Node:
    def __init__(self, data):
        self.data = data
        self.nxt = None

def create_linked_list(values):
    if not values:
        return None
    head = Node(values[0])
    current = head
    for value in values[1:]:
        current.nxt = Node(value)
        current = current.nxt
    return head

def linked_list_to_list(head):
    result = []
    current = head
    while current:
        result.append(current.data)
        current = current.nxt
    return result

def rearrange(node, head):
    if node is None:
        return head

    head = rearrange(node.nxt, head)

    if head is None:
        return None

    if node == head or head.nxt == node:
        node.nxt = None
        return None

    head_next = head.nxt
    head.nxt = node
    node.nxt = head_next
    return head_next

def main_solution(input_list):
    head = create_linked_list(input_list)
    new_head = rearrange(head, head)
    return linked_list_to_list(new_head)
```

