class ProductOfNumbers:

    def __init__(self):
        self.nums = []
        self.prod = [1]
        self.product = 1
        self.length = 1

    def add(self, num: int) -> None:
        self.nums.append(num)
        self.prod.append(self.product*num)
        self.product *= num
        self.length += 1


    def getProduct(self, k: int) -> int:
        if  k == 1:
            return int(self.nums[-1])
        if self.prod[self.length-k-1] > 0:
            return int(self.prod[-1]//self.prod[self.length-k-1])
        else:
            product = 1
            length = len(self.nums)
            for j in range(k):
                product *= self.nums[length-j-1]
                if product == 0:
                    return 0
            return product

def main_solution(nums_sequence, k):
    obj = ProductOfNumbers()
    for num in nums_sequence:
        obj.add(num)
    result = obj.getProduct(k)
    return result
```

