from collections import defaultdict

def main_solution(n, m, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
    vis = [0] * (n + 1)
    dp = [0] * (n + 1)

    def dfs(s):
        if vis[s]:
            return dp[s]
        vis[s] = 1
        for neighbor in graph[s]:
            dp[s] = max(dp[s], dfs(neighbor) + 1)
        return dp[s]

    ans = 0
    for i in range(1, n + 1):
        ans = max(ans, dfs(i))
    return ans
```

