from typing import List

def main_solution(obstacleGrid: List[List[int]]) -> int:
    if not obstacleGrid or obstacleGrid[0][0] == 1 or obstacleGrid[-1][-1] == 1:
        return 0
    height = len(obstacleGrid)
    width = len(obstacleGrid[0])
    dp = [[0] * width for _ in range(height)]

    # Fill last row
    for idx in range(width - 1, -1, -1):
        if obstacleGrid[-1][idx] == 0:
            dp[-1][idx] = 1
        else:
            break
    # Fill last column
    for idx in range(height - 1, -1, -1):
        if obstacleGrid[idx][-1] == 0:
            dp[idx][-1] = 1
        else:
            break
    # Fill the rest
    for h in range(height - 2, -1, -1):
        for w in range(width - 2, -1, -1):
            if obstacleGrid[h][w] == 0:
                dp[h][w] = dp[h + 1][w] + dp[h][w + 1]
    return dp[0][0]
