def main_solution(input_string):
    # Define helper functions
    bchar = lambda x: ('a' <= x <= 'z') or ('A' <= x <= 'Z') or ('0' <= x <= '9')

    def sub(s):
        # Find first alphanumeric character
        start = 0
        while start < len(s) and not bchar(s[start]):
            start += 1

        # If string is empty after trimming leading
        if start >= len(s):
            return ""

        # Find last alphanumeric character
        end = len(s) - 1
        while end > start and not bchar(s[end]):
            end -= 1

        return s[start:end+1]

    return sub(input_string)
```

