import collections

def main_solution(strs):
    # Sort the input strings
    strs.sort()
    # Group strings by their lengths
    length_groups = collections.defaultdict(list)
    for s in strs:
        length_groups[len(s)].append(s)

    # Check lengths in descending order
    for length in sorted(length_groups.keys(), reverse=True):
        group = length_groups[length]
        if len(group) == 1:
            return length
        # Check for unique strings within the same length group
        freq = collections.defaultdict(int)
        for s in group:
            freq[s] += 1
        for s in group:
            if freq[s] == 1:
                return length
    return -1
