def zeroPad(numberString, zeros, right=False):
    '''Returning strings with zeros added to the right or left.'''
    for i in range(zeros):
        if right:
            numberString = numberString + '0'
        else:
            numberString = '0' + numberString
    return numberString

def thirdGradeMultiplication(x, y):
    '''Multiplying two digits using the third grade multiplication algorithm.'''
    x = str(x)
    y = str(y)
    zeroPadding = 0
    partialSum = 0
    for i in range(len(y)-1, -1, -1):
        carry = 0
        partial = ''
        z = 0
        partial = zeroPad(partial, zeroPadding, True)
        for j in range(len(x)-1, -1, -1):
            z = int(x[j]) * int(y[i]) + carry
            w = str(z)
            if len(w) > 1:
                carry = int(w[0])
            else:
                carry = 0
            partial = w[-1] + partial
        if carry > 0:
            partial = str(carry) + partial
        partialSum += int(partial)
        zeroPadding += 1
    return partialSum

def main_solution(x_str, y_str):
    # Convert input strings to integers using the third-grade algorithm
    result = thirdGradeMultiplication(x_str, y_str)
    return int(result)
