        self.stack = []
    def __str__(self):
        if self.is_empty():
            return "Empty"
        s = ""
        for i in self.stack:
            s += str(i) + " "
        return s
    def push(self, item):
        return self.stack.append(item)
    def pop(self):
        return self.stack.pop() if not self.is_empty() else "Empty"
    def peek(self):
        return self.stack[-1] if not self.is_empty() else "Empty"
    def is_empty(self):
        return self.size() == 0
    def size(self):
        return len(self.stack)
    def clear(self):
        return self.stack.clear()

def main_solution(operations):
