class Node:
    def __init__(self, data = None):
        self.data = data
        self.left = self.right = None

class BinaryTree:
    def __init__(self, arr):
        self.root = None
        self.root = self.insertLevelOrder(arr, self.root, 0, len(arr))

    def insertLevelOrder(self, arr, root, i, n): 
        if i < n: 
            temp = Node(arr[i])  
            root = temp  
            root.left = self.insertLevelOrder(arr, root.left, 2 * i + 1, n)  
            root.right = self.insertLevelOrder(arr, root.right, 2 * i + 2, n) 
        return root

    def height(self, node): 
        if node is None: 
            return 0 
        else :
            lheight = self.height(node.left) 
            rheight = self.height(node.right) 
            if lheight > rheight : 
                return lheight+1
            else: 
                return rheight+1

    def printGivenLevel(self, root , level, result_list): 
        if root is None: 
            return
        if level == 1: 
            result_list.append(root.data) 
        elif level > 1 : 
            self.printGivenLevel(root.left , level-1, result_list) 
            self.printGivenLevel(root.right , level-1, result_list)

    def get_level_order(self):
        result = []
        h = self.height(self.root)
        for i in range(1, h+1):
            self.printGivenLevel(self.root, i, result)
        return result

def main_solution(arr):
    btree = BinaryTree(arr)
    return btree.get_level_order()
